async showClone() {
    if (Store.editor.hasChanges) {
        const confirmed = await this.promptDiscardChanges();
        if (!confirmed) return;
    }
    this.showCloneDialog = true;
    Store.showCloneDialog.set(true);
}

showCreateVariation() {
    this.showCreateVariationDialog = true;
}

cancelCreateVariation() {
    this.showCreateVariationDialog = false;
}

async confirmClone() {
    const osi = this.fragment.getFieldValue('osi', 0);
    if (this.fragment.model.path === CARD_MODEL_PATH && !this.osiClone && !osi) {
        showToast('Please select an offer', 'negative');
        return;
    }

    try {
        this.cloneInProgress = true;
        await this.repository.copyFragment(this.titleClone, this.osiClone, this.tagsClone);
        this.cancelClone();
    } catch (error) {
        console.error('Error cloning fragment:', error);
    } finally {
        this.cloneInProgress = false;
    }
}

cancelClone() {
    this.showCloneDialog = false;
    Store.showCloneDialog.set(false);
    this.tagsClone = [];
    this.osiClone = null;
}

handleTagsChangeOnClone(e) {
    const value = e.target.getAttribute('value');
    this.tagsClone = value ? value.split(',') : [];
}

onOstSelectClone = ({ detail: { offerSelectorId, offer } }) => {
    if (!offer) return;
    this.osiClone = offerSelectorId;
};

async saveFragment() {
    try {
        await this.repository.saveFragment(this.fragmentStore, true);
    } catch (error) {
        console.error('Failed to save fragment:', error);
        showToast(`Failed to save fragment: ${error.message}`, 'negative');
        throw error;
    }

async copyFragment(updatedTitle, osi, tags = []) {
    try {
        this.operation.set(OPERATIONS.CLONE);
        const result = await this.aem.sites.cf.fragments.copy(this.fragmentInEdit);
        let savedResult = result;
        const needsSave = (updatedTitle && updatedTitle !== result.title) || osi;
        if (needsSave) {
            if (updatedTitle && updatedTitle !== result.title) {
                result.title = updatedTitle;
            }
            result.fields.forEach((field) => {
                if (osi && field.name === 'osi') {
                    field.values = [osi];
                }
            });
            savedResult = await this.aem.sites.cf.fragments.save(result);
        }
        if (tags.length) {
            savedResult.newTags = tags;
            await this.aem.saveTags(savedResult);
            savedResult = await this.aem.sites.cf.fragments.getById(savedResult.id);
        }
        // Apply corrector transformer before caching
        const surface = this.search.value.path?.split('/').filter(Boolean)[0]?.toLowerCase();
        applyCorrectorToFragment(savedResult, surface);
        const newFragment = await this.#addToCache(savedResult);

        const sourceStore = generateFragmentStore(newFragment);
        sourceStore.get().hasChanges = false;
        sourceStore.skipVariationDetection = true;
        Store.fragments.list.data.set((prev) => [sourceStore, ...prev]);

        // Reset changes on the current fragment to prevent discard prompt during navigation
        Store.editor.resetChanges();

        await router.navigateToFragmentEditor(newFragment.id);

        this.operation.set();
        Events.fragmentAdded.emit(newFragment.id);
        showToast('Fragment successfully copied.', 'positive');
        return true;
    } catch (error) {
        this.operation.set();
        this.processError(error, 'Failed to copy fragment.');
    }
    return false;
}

